import{_ as i,l as r,o as e,c as l,v as o,p as s,x as t,d as p,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"制度与增长","description":"","frontmatter":{"title":"制度与增长","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/institutions-acemoglu.md","filePath":"econ/institutions-acemoglu.md","lastUpdated":1789023840000}'),c={name:"econ/institutions-acemoglu.md"};function h(E,a,m,u,_,f){const n=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="制度与增长" tabindex="-1">制度与增长 <a class="header-anchor" href="#制度与增长" aria-label="Permalink to &quot;制度与增长&quot;">​</a></h1><div class="epigraph"><p>地理与文化可以进入历史，但进入人均收入的主通道，是一套能否约束掠夺、保护投资的制度。</p><footer>—— Acemoglu, Johnson and Robinson, The Colonial Origins of Comparative Development, AER 2001</footer></div><p><a href="/econ/directed-technical-change">上一课</a>已经让研发有方向：相对利润引导技术朝哪种要素偏。利润要能被占有，才谈得上引导。本课的缺口是：产权、约束执政者、进入壁垒——制度——如何成为增长核算里那块巨大 \\(A\\) 的深层原因。Acemoglu、Johnson 与 Robinson（AJR）用殖民起源做识别；统一增长下一课才问马尔萨斯约束何时松开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>发展核算把跨国 \\(Y/L\\) 的大头留给剩余 \\(A\\)；错配课说 \\(A\\) 含楔子；有偏技术说 \\(A\\) 有方向。都还没回答：为什么有的国家长期保住投资激励，有的把剩余收成租金。AJR 的缺口是把<strong>制度</strong>当成比较发展的根本原因，而不是再估一条索洛回归。地理决定论把气候与疾病写成直接生产力；AJR 允许地理进入，但主路径是历史形成的制度。</p><p><span class="marginnote">「制度」在此指约束与激励的规则：征收风险、合同执行、政治参与。不是文化口号，也不是当期的监管条文清单。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>殖民样本：欧洲人定居的地方带去产权与约束；开采殖民地留下榨取制度。定居者死亡率作为工具变量，代理历史上能否定居，从而代理早期制度，再接到当代制度与收入。第一阶段不是「疾病直接让人穷」，而是疾病影响定居模式。Hall–Jones 已把制度写进 \\(A\\) 的叙事；AJR 提供的是因果设计，不是又一次水平分解。</p>',8)),(e(),s(A,null,{default:t(()=>[d(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEO%5B%22%E5%9C%B0%E7%90%86%20%2F%20%E7%96%BE%E7%97%85%22%5D%20--%3E%20SET%5B%22%E5%AE%9A%E5%B1%85%E4%B8%8E%E6%AE%96%E6%B0%91%E7%AD%96%E7%95%A5%22%5D%0A%20%20SET%20--%3E%20INST%5B%22%E6%97%A9%E6%9C%9F%E5%88%B6%E5%BA%A6%22%5D%0A%20%20INST%20--%3E%20NOW%5B%22%E5%BD%93%E4%BB%A3%E4%BA%A7%E6%9D%83%E4%B8%8E%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20NOW%20--%3E%20Y%5B%22%E4%BA%BA%E5%9D%87%E6%94%B6%E5%85%A5%20%2F%20A%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>有偏技术在制度差的地方会被导向寻租或镇压，而不是技能互补的生产性研发。上一课的相对利润，暗含利润不被征收。本课把这一句写进增长主干。</p><h3 id="工具不是地理决定论" tabindex="-1">工具不是地理决定论 <a class="header-anchor" href="#工具不是地理决定论" aria-label="Permalink to &quot;工具不是地理决定论&quot;">​</a></h3><p>死亡率 IV 依赖排除限制：历史上的疾病通过制度而非通过当代健康或气候进入收入。争议围绕这一点，本课不假装没有。识别失败不等于「制度无关」；它只说这一条殖民通道的因果权重被高估。</p><h3 id="殖民样本不是全部发展中国家" tabindex="-1">殖民样本不是全部发展中国家 <a class="header-anchor" href="#殖民样本不是全部发展中国家" aria-label="Permalink to &quot;殖民样本不是全部发展中国家&quot;">​</a></h3><p>IV 设计用的是曾经被殖民的截面。从未被殖民的国家、社会主义转型，要另找识别，不能把死亡率工具直接外推。</p><p>本课要的是制度作为根本原因的结构，不是一张对所有国都成立的弹性表。增长回归的政策模拟仍受卢卡斯批判约束。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>榨取制度提高征收风险，压低投资与研发的私人回报，发展核算里就表现为低 \\(A\\) 与低 \\(K\\)。包容制度降低这道楔子，并允许进入——错配缩小，有偏创新朝生产性要素走。政治均衡可以锁定：既得利益阻止改制度，于是穷与制度差互相维持。这与索洛 \\(s\\) 外生不同：储蓄率本身被安全的产权托住。</p><p>反向因果是显然的：富国更能买好制度。IV 与历史叙事要处理的就是这句。本课不把某一殖民地的点估计写成普适弹性。马尔萨斯世界里，制度改善可能先变成人口，而不是人均 \\(y\\)——下一课的缺口。</p><p>有偏技术在包容制度下更可能朝可占有的生产性技能偏；在榨取制度下，同样的研发预算可以朝征税技术、镇压或垄断壁垒偏。加总 \\(g\\) 看起来可以差不多，要素溢价与进入完全不同。因此制度不是在 \\(A\\) 外面另加一个哑变量，而是改写上一课相对利润那一项里「利润归谁」。</p><p><span class="marginnote">法律起源、奴隶贸易、殖民者身份是平行的历史识别，不是对 AJR 的否定。主干只要：制度进入激励，从而进入 \\(A\\) 与 \\(K\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重跑 AJR 表，不把制度写成交易价差或 CIP。外汇平价仍在<a href="/quant/irp">量化栏</a>。也不把「改革口号」当识别：同一套条文，执行与政治约束可以完全不同。增长回归的政策含义仍受卢卡斯批判约束。</p><p>地理、文化与制度可以共线。AJR 的策略是让地理主要走历史制度，而不是否认气候进入生产。把本课读成「只有制度、没有地理」，是把识别策略当成本体论。错配课的楔子可以是制度的当期表现；AJR 问的是楔子为何持久——政治均衡锁定，不是生产函数形式。</p><p>后课默认：谈到跨国 \\(A\\) 的深层原因，制度是候选的根本原因，不是又一个残差标签。下一课：在制度已经能保护剩余的世界上，人均收入为何长期钉在生存水平，又如何脱离。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>有偏技术需要可占有的利润；制度决定利润是否被征收。</li><li>AJR：殖民定居模式 → 制度 → 当代收入。</li><li>地理可以进入历史，主通道仍是激励规则。</li><li>IV 排除限制有争议，不等于制度可以从核算里删掉。</li><li>出处：Acemoglu, Johnson and Robinson, <em>AER</em> 2001。</li></ul>',17))])}const T=i(c,[["render",h]]);export{b as __pageData,T as default};
